package com.srm.inventory.controller;
import com.srm.inventory.dto.*; import com.srm.inventory.entity.*; import com.srm.inventory.service.OrderService; import jakarta.validation.Valid; import org.springframework.http.*; import org.springframework.web.bind.annotation.*; import java.util.*;
@RestController @RequestMapping("/api/orders") public class OrderController { private final OrderService service; public OrderController(OrderService s){service=s;} @GetMapping public List<CustomerOrder> list(@RequestParam(required=false) OrderStatus status){return service.list(status);} @GetMapping("/{id}") public CustomerOrder get(@PathVariable Long id){return service.get(id);} @PostMapping public ResponseEntity<CustomerOrder> create(@Valid @RequestBody OrderRequest r){return ResponseEntity.status(HttpStatus.CREATED).body(service.create(r));} @PatchMapping("/{id}/status") public CustomerOrder status(@PathVariable Long id,@Valid @RequestBody StatusRequest r){return service.updateStatus(id,r);} @PatchMapping("/{id}/payment") public CustomerOrder payment(@PathVariable Long id,@Valid @RequestBody PaymentRequest r){return service.updatePayment(id,r);} @DeleteMapping("/{id}") @ResponseStatus(HttpStatus.NO_CONTENT) public void delete(@PathVariable Long id){service.delete(id);} }
